def calculate_D_n_plus_1_bound(task_set, U_total):
    lcm_periods = calculate_lcm([t.T for t in task_set])

    sum_term = 0
    for task_i in task_set:
        sum_term += task_i.U * max(0, task_i.T - task_i.D)

    bound_2 = task_set[-1].D # D_n
    if U_total < 1:
        bound_2 = max(bound_2, (1 / (1 - U_total)) * sum_term)
    else:
        bound_2 = float('inf') # If U_total >= 1, this bound is infinite

    return min(lcm_periods, bound_2)

def calculate_blocking(task_i, task_set):
    B_i = 0
    # Assuming task_set is sorted by priority/deadline
    for k in range(task_i.id + 1, len(task_set)):
        B_i = max(B_i, task_set[k].q_max)
    return B_i

def calculate_beta_FP(task_i, task_set, A_FP):
    max_slack = -float('inf')
    for a in A_FP:
        if a > task_i.D:
            continue

        total_RBF = 0
        for j in range(task_i.id + 1):
            total_RBF += RBF(a, task_set[j])

        slack = a - total_RBF
        max_slack = max(max_slack, slack)
    return max_slack

def calculate_beta_EDF(task_i, task_set, A_EDF, D_n_plus_1_bound):
    min_slack = float('inf')

    # Determine D_i_plus_1
    D_i_plus_1 = D_n_plus_1_bound
    if task_i.id + 1 < len(task_set):
        D_i_plus_1 = task_set[task_i.id + 1].D

    for a in A_EDF:
        if not (task_i.D <= a < D_i_plus_1):
            continue

        total_DBF = 0
        for task_j in task_set:
            total_DBF += DBF(a, task_j)

        slack = a - total_DBF
        min_slack = min(min_slack, slack)
    return min_slack

def generate_A_EDF(task_set, D_n_plus_1_bound):
    A_EDF_points = set()
    for task_j in task_set:
        # Generate k*T_j + D_j up to D_n_plus_1_bound
        k = 0
        while True:
            point = k * task_j.T + task_j.D
            if point > D_n_plus_1_bound:
                break
            A_EDF_points.add(point)
            k += 1
    return sorted(list(A_EDF_points))

def calculate_Q_k(k, beta_values):
    # beta_values is a list where beta_values[i] corresponds to beta_{i+1}
    # Q_k is for task k (0-indexed)
    if k == 0:
        return float('inf') # Q_1 for the first task

    min_beta_prev = float('inf')
    for i in range(k):
        min_beta_prev = min(min_beta_prev, beta_values[i])
    return min_beta_prev

# Iterative form:
def calculate_Q_k_iterative(Q_prev, beta_prev):
    return min(Q_prev, beta_prev)

def is_schedulable_theorem1(task_set, scheduler_type):
    for task_i in task_set:
        B_i = calculate_blocking(task_i, task_set)
        if scheduler_type == 'FP':
            beta_i = calculate_beta_FP(task_i, task_set, A_FP)
        elif scheduler_type == 'EDF':
            beta_i = calculate_beta_EDF(task_i, task_set, A_EDF, D_n_plus_1_bound)

        if B_i > beta_i:
            return False # Task set is not schedulable
    return True # Task set is schedulable

def is_schedulable_theorem2(task_set, Q_values):
    # Q_values is a list where Q_values[k-1] corresponds to Q_k
    # Assuming task_set is 0-indexed, so task_set[k-1] is tau_k
    # And Q_values[k] is Q_{k+1}

    # For k from 1 to n+1 (paper's notation)
    # In 0-indexed, for k from 0 to n
    for k_idx in range(len(task_set) + 1):
        q_max_k = 0
        if k_idx < len(task_set):
            q_max_k = task_set[k_idx].q_max

        Q_k = Q_values[k_idx] # Q_values[0] is Q_1, Q_values[1] is Q_2, etc.

        if q_max_k > Q_k:
            return False # Task set is not schedulable
    return True # Task set is schedulable
